package bottlesong

import "fmt"

var numbers = map[int]string{
	0: "no",
	1: "One",
	2: "Two",
	3: "Three",
	4: "Four",
	5: "Five",
	6: "Six",
	7: "Seven",
	8: "Eight",
	9: "Nine",
	10: "Ten",
}

func Recite(startBottles, takeDown int) []string {
	verses := make([]string, 0, takeDown*5)
	for i := 0; i < takeDown; i++ {
		bottles := startBottles - i
		if i > 0 {
			verses = append(verses, "")
		}
		verses = append(verses, verse(bottles)...)
	}
	return verses
}

func verse(bottles int) []string {
	return []string{
		fmt.Sprintf("%s green bottle%s hanging on the wall,", numbers[bottles], plural(bottles)),
		fmt.Sprintf("%s green bottle%s hanging on the wall,", numbers[bottles], plural(bottles)),
		"And if one green bottle should accidentally fall,",
		fmt.Sprintf("There'll be %s green bottle%s hanging on the wall.", numbers[bottles-1], plural(bottles-1)),
	}
}

func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

